with base as (select *, date_add(ends_on, 82) as ends_on_plus_82d, round(datediff(ends_on, starts_on) / 30, 1) as months_starts_on_to_ends_on, coalesce(channel, 'OTHER') as channel_clean from promotions where discount_pct <= 0.3 and channel is not null) select *, lead(discount_pct, 1) over (order by ends_on_plus_82d asc, id asc) as next_discount_pct, lead(months_starts_on_to_ends_on, 1) over (order by ends_on asc, id asc) as next_months_starts_on_to_ends_on, lag(discount_pct, 1, 0) over (partition by date_trunc('week', ends_on) order by ends_on asc, id asc) as prev_discount_pct, row_number() over (partition by channel order by months_starts_on_to_ends_on desc, id asc) as row_seq from base;
